def arch():
    o=['<ol class="arch rv">']
    for i,(ic,n,d,pl,what,bib,kind) in enumerate(ARCH):
        o.append(f'<li style="--i:{i}" class="{"cmp" if kind=="对照" else "ok"}"><span class="ai">{ic}</span><div class="ab"><div class="ah"><b>{E(n)}</b><span class="ad">{E(d)}</span><span class="ap">📍{E(pl)}</span><span class="ak">{"⚖️ 对照" if kind=="对照" else "✅ 印证"}</span></div><p>{rich(what)}</p><p class="abib">{rich(bib)}</p></div></li>')
    return ''.join(o)+'</ol>'
